mapper.select:
SELECT t.id, t.title, t.status, t.priority, t.plan_start_time, t.plan_end_time, t.start_time, t.end_time, -- 计算是否逾期：已完成不算逾期，未完成且超过计划结束时间算逾期 CASE WHEN t.status = 4 THEN FALSE WHEN t.plan_end_time IS NULL THEN FALSE WHEN NOW() > t.plan_end_time THEN TRUE ELSE FALSE END AS is_overdue, -- 查询最近提交时间（如果有任务记录表的话） ( SELECT MAX(tr.create_time) FROM task_record tr WHERE tr.task_id = t.id AND tr.action_type = 1 ) AS latest_submit_time, -- 负责人信息（taskRole = 1 表示负责人） owner_su.user_id AS owner_user_id, owner_su.avatar AS owner_avatar, owner_su.nick_name AS owner_nick_name FROM task t -- 关联负责人 LEFT JOIN task_user owner_tu ON owner_tu.task_id = t.id AND owner_tu.task_role = 1 LEFT JOIN sys_user owner_su ON owner_su.user_id = owner_tu.user_id AND owner_su.del_flag = 0
t.del_flag = 0
AND t.title LIKE CONCAT('%', #{query.title}, '%')
AND t.status = #{query.status}
AND t.priority = #{query.priority}
AND EXISTS ( SELECT 1 FROM task_user filter_tu WHERE filter_tu.task_id = t.id AND filter_tu.user_id = #{query.userId} )
AND t.create_time >= #{query.startTime}
AND t.plan_end_time <= #{query.endTime}
ORDER BY t.create_time DESC
